uniform float iTime;
uniform vec3 iResolution;
uniform vec4 iMouse;
uniform float iDist;          // Control Zoom/Scale
uniform float iIntensity;     // Control Brightness/Glow
uniform float u_segments;     // Number of radial slices
uniform float u_speed;        // Speed of internal rotation
uniform float u_pulse_speed;  // Global speed multiplier for animation
uniform float u_purple_tint;  // Control for the purple highlight
uniform float u_neural_complexity; // Fractal iterations for neural paths
uniform float u_flow_depth;   // Perception of 3D depth in flow

varying vec2 vUv;

// Palette function for color cycling
vec3 palette( float t ) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);
    return a + b * cos( 6.28318 * (c * t + d) );
}

// 2D Rotation helper
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

void main() {
    // Normalize coordinates
    vec2 uv = (vUv * 2.0 - 1.0);
    uv.x *= iResolution.x / iResolution.y;

    // Time driver
    float t = iTime * u_pulse_speed;

    // --- Raymarching-lite / 3D Neural Flow setup ---
    // We treat 'z' as a progression into the "neural network"
    vec3 finalColor = vec3(0.0);

    // Kaleidoscope/Radial Pre-process
    float r = length(uv);
    float angle = atan(uv.y, uv.x);
    float segmentAngle = 6.28318 / max(u_segments, 1.0);
    angle = mod(angle, segmentAngle);
    angle = abs(angle - segmentAngle * 0.5);
    uv = vec2(cos(angle), sin(angle)) * r;

    // Apply global zoom
    uv *= (3.0 / clamp(iDist, 0.1, 20.0));

    // Iterative Ray/Slice accumulation for 3D depth
    for (float j = 0.0; j < 3.0; j++) {
        // Offset each "layer" in depth
        float depth = j * u_flow_depth * 0.1;
        vec2 layerUv = uv * (1.0 + depth);

        // Internal layer rotation
        layerUv *= rot(iTime * u_speed * 0.2 + j);

        vec2 uv0 = layerUv;

        // Iterative fractal folding to simulate neural dendrites
        for (float i = 0.0; i < u_neural_complexity; i++) {
            // Fold the space
            layerUv = abs(layerUv) - 0.5;
            layerUv *= rot(t * 0.5 + i * 0.3);
            layerUv = fract(layerUv * 1.5) - 0.5;

            // Distance to neural "synapses"
            float d = length(layerUv) * exp(-length(uv0));

            // Color based on depth and iteration
            vec3 col = palette(length(uv0) + i * 0.2 + t * 1.5 + j * 0.5);

            // Create flowing wave pulses
            d = sin(d * (8.0 + j) + t * 5.0) / 8.0;
            d = abs(d);

            // Neon glow effect (Neural spark)
            // Sharpen the glow for "neural wire" look
            float spark = pow(0.008 / d, 1.1);

            // Apply depth fading
            spark *= (1.0 / (1.0 + depth * 2.0));

            finalColor += col * spark;
        }
    }

    // --- Neural Post-Processing ---
    // Calculate luminance for highlights
    float luminance = dot(finalColor, vec3(0.2126, 0.7152, 0.0722));

    // Purple Tone mapping (Synaptic Hue)
    vec3 purpleTone = vec3(0.7, 0.4, 1.0);

    // Mix the original color with a purple-toned version specifically in the highlights
    vec3 tintedColor = mix(finalColor, finalColor * purpleTone + vec3(0.1, 0.0, 0.2), u_purple_tint * smoothstep(0.1, 0.8, luminance));

    // Add a slight vignette for 3D tunnel feel
    float vignette = smoothstep(2.0, 0.5, length(vUv - 0.5) * 2.0);
    tintedColor *= vignette;

    // Final intensity multiplier
    gl_FragColor = vec4(tintedColor * iIntensity, 1.0);
}
